import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

/** 部署后自检：工作目录、环境变量、日志目录可写性。 */
public final class EnvCheck {
    public static void main(String[] args) throws Exception {
        System.out.println("user.dir = " + System.getProperty("user.dir"));
        System.out.println("java.home = " + System.getProperty("java.home"));
        System.out.println("PATH = " + System.getenv("PATH"));
        System.out.println("SPRING_PROFILES_ACTIVE = " + System.getenv("SPRING_PROFILES_ACTIVE"));

        Map<String, String> env = System.getenv();
        env.keySet().stream()
           .filter(k -> k.startsWith("LEARNHUB_"))
           .sorted()
           .forEach(k -> System.out.println(k + "=" + env.get(k)));

        Path logDir = Path.of(System.getProperty("learnhub.log.dir", "logs"));
        Files.createDirectories(logDir);
        System.out.printf("logDir=%s writable=%s%n", logDir.toAbsolutePath(), Files.isWritable(logDir));

        Path probe = logDir.resolve("env-check.tmp");
        Files.writeString(probe, "ok");
        Files.delete(probe);

        String path = env.getOrDefault("PATH", "");
        if (!path.contains("/usr/bin")) {
            System.err.println("WARN: PATH 缺少 /usr/bin，cron 与 systemd 下最常见");
        }
        System.out.println("OK");
    }
}
